content:
{
  "root_cause": "The color contrast for the selected day button (data-pika-day="23") fails WCAG 1.4.3 because the selected state uses white text (#fff) on a blue background (#33aaff) with a contrast ratio of only ~2.9:1. The default button state (#666 on #f5f5f5) also fails at ~2.25:1. The automated rule flagged the selected button for day 23.",
  "repair_strategy": "Darken the background colors for selected, range, and default button states to achieve at least 4.5:1 contrast with white text, and darken the default button text color for non-overridden states.",
  "edits": [
    {
      "path": "css/pikaday.css",
      "sha256": "199cb17f38ab8a1db1d510f41892b8253e36b5a80bf1af9478ae37b3ee113047",
      "before": ".pika-button {
    cursor: pointer;
    display: block;
    box-sizing: border-box;
    -moz-box-sizing: border-box;
    outline: none;
    border: 0;
    margin: 0;
    width: 100%;
    padding: 5px;
    color: #666;
    font-size: 12px;
    line-height: 15px;
    text-align: center;
    background: #f5f5f5;
    height: initial;
}",
      "after": ".pika-button {
    cursor: pointer;
    display: block;
    box-sizing: border-box;
    -moz-box-sizing: border-box;
    outline: none;
    border: 0;
    margin: 0;
    width: 100%;
    padding: 5px;
    color: #222;
    font-size: 12px;
    line-height: 15px;
    text-align: center;
    background: #f5f5f5;
    height: initial;
}"
    },
    {
      "path": "css/pikaday.css",
      "sha256": "199cb17f38ab8a1db1d510f41892b8253e36b5a80bf1af9478ae37b3ee113047",
      "before": ".is-selected .pika-button,
.has-event .pika-button {
    color: #fff;
    font-weight: bold;
    background: #33aaff;
    box-shadow: inset 0 1px 3px #178fe5;
    border-radius: 3px;
}",
      "after": ".is-selected .pika-button,
.has-event .pika-button {
    color: #fff;
    font-weight: bold;
    background: #002244;
    box-shadow: inset 0 1px 3px #001122;
    border-radius: 3px;
}"
    },
    {
      "path": "css/pikaday.css",
      "sha256": "199cb17f38ab8a1db1d510f41892b8253e36b5a80bf1af9478ae37b3ee113047",
      "before": ".is-startrange .pika-button {
    color: #fff;
    background: #6CB31D;
    box-shadow: none;
    border-radius: 3px;
}",
      "after": ".is-startrange .pika-button {
    color: #fff;
    background: #003300;
    box-shadow: none;
    border-radius: 3px;
}"
    },
    {
      "path": "css/pikaday.css",
      "sha256": "199cb17f38ab8a1db1d510f41892b8253e36b5a80bf1af9478ae37b3ee113047",
      "before": ".is-endrange .pika-button {
    color: #fff;
    background: #33aaff;
    box-shadow: none;
    border-radius: 3px;
}",
      "after": ".is-endrange .pika-button {
    color: #fff;
    background: #002244;
    box-shadow: none;
    border-radius: 3px;
}"
    }
  ],
  "expected_accessibility_effect": "Selected day buttons, range buttons, and default day buttons now meet WCAG 1.4.3 contrast requirements (>=4.5:1) for text against background, improving readability for users with low vision.",
  "functional_risks": [
    "Color changes are visual only; no functional behavior is altered.",
    "The new dark blue (#002244) and dark green (#003300) may appear different from the original theme but maintain the same semantic meaning."
  ],
  "verification_requirements": [
    "Automated color-contrast rule should no longer flag button[data-pika-day="23"] in selected state.",
    "Default day buttons (non-selected, non-today, non-disabled) should pass contrast with #222 on #f5f5f5.",
    "Start-range and end-range buttons should pass contrast with white text on their new backgrounds."
  ]
}
